import express from 'express';
import NodegenRequest from '@/http/interfaces/NodegenRequest';
import { ForbiddenException } from '@/http/nodegen/errors';
import { isSuperAdmin } from '@/constants/ROLES';

/** Permission codes of the /admin/** routes, generated by the spec as api + path + verb. */
const ADMIN_PERMISSION_PREFIX = 'apiAdmin';

/**
 * Called by the generated routes for every operation carrying an x-permission
 * code (every route except /health). The session middleware has already run,
 * so req.sessionData is set for any route that reaches here.
 *
 * Rule: routes under /admin need the SUPER_ADMIN system role; everything else
 * is open to any signed in user. Extend here (per-code permissions, per-record
 * ownership) as the product grows.
 */
class PermissionService {
  isAdminPermission(permission: string): boolean {
    return permission.startsWith(ADMIN_PERMISSION_PREFIX);
  }

  middleware(req: NodegenRequest, res: express.Response, next: express.NextFunction, permission: string) {
    if (this.isAdminPermission(permission) && !isSuperAdmin(req.sessionData?.userRoles)) {
      next(new ForbiddenException('This action needs the SUPER_ADMIN role'));
      return;
    }
    next();
  }
}
export default new PermissionService();
